   "titolo": "Macron accusa i leader stranieri di sfruttare le proteste francesi",
   "orig": "Macron accuses foreign leaders of exploiting French riots",
   "lead": "Il presidente francese Emmanuel Macron ha accusato alcuni leader stranieri, tra cui Donald Trump e Benjamin Netanyahu, di aver diffuso informazioni fuorvianti e fatto commenti superficiali sui disordini di piazza avvenuti in Francia. Secondo Macron, tali interventi sarebbero motivati da calcoli politici in vista delle imminenti elezioni nei rispettivi Paesi. Lo riferisce BBC News.",
   "more": [
    "Le tensioni politiche internazionali spesso si riflettono nell'uso mediatico delle crisi interne di altri Stati. Quando si verificano proteste o disordini di forte impatto visivo, i leader politici di altre nazioni possono commentare gli eventi per influenzare i rispettivi elettori o per distogliere l'attenzione dai problemi interni."
   ],
