   "id": "zf2293a79",
   "sez": "italia",
   "titolo": "TikTok avvia una task force per gestire i contenuti sulle proteste",
   "orig": "Proteste e battage sui social media, TikTok avvia una task force",
   "lead": "In seguito alle recenti proteste e alla diffusione virale di contenuti legati ai disordini sui social media, la piattaforma TikTok ha deciso di intervenire istituendo una task force dedicata. L'azienda ha rafforzato le attività di moderazione, provvedendo alla rimozione di diversi video e al blocco di account ritenuti non conformi alle regole della community. Lo riferisce ANSA.",
   "more": [
    "Le piattaforme di condivisione video e social network utilizzano strumenti di moderazione automatica e team umani per limitare la diffusione di contenuti che incitano alla violenza o documentano disordini urbani. La gestione dei flussi informativi digitali durante le crisi di piazza rappresenta una sfida complessa per le aziende tecnologiche."
   ],
