   "id": "z9c67991d",
   "sez": "mondo",
   "titolo": "La Corte Suprema conferma lo stop alla politica anti-trans nelle carceri federali",
   "orig": "Supreme Court upholds pause on Trump's anti-trans prison policy",
   "lead": "La Corte Suprema degli Stati Uniti ha stabilito che l'amministrazione deve continuare a garantire le cure per l'affermazione di genere ai detenuti presenti nelle carceri federali. La decisione è arrivata mentre prosegue il contenzioso giudiziario sulle misure promosse dall'amministrazione per modificare la precedente politica sanitaria carceraria. Lo riferisce NPR.",
   "more": [
    "Il sistema carcerario federale statunitense è spesso al centro di battaglie legali riguardanti i diritti costituzionali e sanitari dei detenuti. Le decisioni della Corte Suprema in materia di trattamenti medici specifici definiscono gli obblighi assistenziali dello Stato nei confronti della popolazione carceraria durante il corso dei procedimenti giudiziari."
   ],
