   "titolo": "Esperti marittimi chiedono maggiori controlli sulle emissioni delle navi nei porti malesi",
   "orig": "Haze or ship fumes? Maritime experts want closer watch on vessel emissions at Malaysian ports",
   "lead": "Le autorità portuali e marittime della Malaysia dovrebbero intensificare i controlli sull'impatto ambientale delle emissioni prodotte dalle navi commerciali. Secondo gli esperti del settore, è necessario esaminare con maggiore attenzione il contributo effettivo del traffico navale ai livelli di inquinamento atmosferico nelle aree costiere. Lo riferisce Malay Mail.",
   "more": [
    "Il trasporto marittimo commerciale è una fonte significativa di emissioni inquinanti nei porti e nelle zone costiere densamente popolate. L'adozione di normative più rigide e di sistemi di monitoraggio avanzati consente di ridurre l'impatto ambientale delle attività portuali sulla qualità dell'aria."
   ],
