   "lead": "Una giuria nello Stato americano del Nuovo Messico ha condannato la società Meta a pagare una sanzione di 25 miliardi di dollari. La decisione è giunta dopo che l'azienda è stata ritenuta responsabile di aver ingannato i consumatori in merito alle politiche di gestione e protezione della privacy dei dati personali. Lo riferisce CNA.",
