   "titolo": "Scontri a Milano: identificato un undicenne, il governo valuta nuove misure di sicurezza",
   "orig": "Scontri Milano: il più giovane identificato ha 11 anni. Piantedosi: 'Nessuna evidenza che fossero manipolati'. In arrivo i parà della Folgore",
   "lead": "A seguito dei recenti disordini e atti di vandalismo avvenuti a Milano nel fine settimana, il comitato per la sicurezza riunitosi in prefettura ha esaminato la situazione, registrando l'identificazione di un minore di undici anni immortalato nei filmati della guerriglia urbana. Il ministro dell'Interno Matteo Piantedosi ha dichiarato che non vi sono evidenze di manipolazione dei giovani coinvolti, mentre il sindaco Giuseppe Sala ha invocato rigore nel controllo e nella repressione. Da parte sua, il vicepremier Matteo Salvini ha sottolineato che nulla resterà impunito, mentre l'esecutivo valuta l'introduzione di un nuovo decreto e l'impiego dei paracadutisti della Folgore per la sicurezza. Lo riferisce ANSA.",
   "more": [
    "La gestione dell'ordine pubblico nelle grandi aree urbane e il fenomeno della partecipazione di giovanissimi a episodi di violenza di piazza aprono un confronto complesso tra le esigenze di sicurezza, le politiche di prevenzione sociale e l'uso degli strumenti normativi e militari per il controllo del territorio."
   ],
