   "lead": "Durante Art Basel 2026, sculture di animali imbottite realizzate da Cosima von Bonin occupano le gallerie storiche del Petit Palais a Parigi. Queste opere installate interrompono la solennità delle figure classiche presenti nel museo. Lo riferisce Designboom.",
