   "lead": "In Italia si registrano criticità nei pagamenti degli arretrati relativi alle posizioni economiche del personale ATA, fermi al mese di agosto e privi della mensilità di settembre. A sollevare il problema è Sorrentino di Anief-Condir, che segnala anche la possibilità di nuovi scorrimenti delle graduatorie. Lo riferisce Orizzonte Scuola.",
