   "orig": "Here's how much wealth New Zealanders have tied up in property",
   "lead": "Nel corso dell'ultimo anno, beni immobili residenziali per un valore complessivo di 78,1 miliardi di dollari hanno cambiato proprietario in Nuova Zelanda. I dati emergono da un'analisi condotta da una società specializzata nel settore immobiliare. Lo riferisce RNZ.",
