   "titolo": "Scandalo nel basket greco: sei arresti, tra cui il presidente della Federazione",
   "orig": "Scandal in Greek Basketball: Six people arrested, among them Federation president",
   "lead": "Sei persone sono state arrestate nell'ambito di un'indagine su una presunta combine nel basket greco. Tra i soggetti coinvolti e arrestati vi è anche Vangelis Liolios, presidente della Federazione cestistica ellenica. Nel corso delle perquisizioni, le forze dell'ordine hanno rinvenuto 820.000 euro in contanti all'interno della cassaforte di un arbitro. Lo riferisce Keep Talking Greece.",
