   "lead": "Negli Stati Uniti, la società Brayman ha avviato un'azione legale chiedendo un risarcimento in relazione a una miscela di calcestruzzo impiegata per la costruzione dei pali di fondazione del tunnel del Potomac. Secondo la causa giudiziaria, la corretta esecuzione dei lavori dipendeva da specifiche caratteristiche di resistenza del materiale. Lo riferisce Engineering News-Record.",
