   "lead": "Il governo nazionale della Papua Nuova Guinea ha avviato un'operazione di soccorso coordinata per portare aiuti umanitari alle comunità vulnerabili delle isole Lou e Rambutso, nella provincia di Manus. L'intervento prevede l'invio di forniture alimentari d'emergenza, scorte d'acqua potabile e squadre di vigili del fuoco per fronteggiare la grave siccità. Lo riferisce Post-Courier.",
