   "lead": "Il partito ACT in Nuova Zelanda ha avanzato la proposta di eliminare il contributo statale ai conti KiwiSaver, prevedendo in alternativa l'esenzione fiscale sui guadagni derivanti dagli investimenti nei fondi pensione. La misura solleva interrogativi sulla sua equità sociale. Lo riferisce RNZ.",
