   "lead": "Uno studio condotto negli Stati Uniti da Philip Baiden dell'Università del Texas ad Arlington e dai suoi colleghi, pubblicato sulla rivista PLOS One, evidenzia che solitudine, limitazioni funzionali e carenza di supporto sociale sono associati in modo indipendente alla depressione tra i sopravvissuti alle patologie oncologiche. Lo riferisce Medical Xpress.",
