   "sez": "spazio",
   "titolo": "La sonda Solar Orbiter traccia i giganteschi 'switchback' magnetici direttamente fino al Sole",
   "orig": "Solar Orbiter Traces Giant Magnetic Switchbacks Directly Back to the Sun",
   "lead": "La sonda spaziale Solar Orbiter, impegnata nell'osservazione dell'attività solare, ha registrato un incontro fortuito con un fenomeno di fisica solare noto come 'switchback'. Grazie a questa osservazione casuale, un team di ricercatori guidato da Jesse T. Coburn è riuscito a tracciare queste inversioni magnetiche giganti riconducendole direttamente alla loro origine nella corona solare, come descritto in un nuovo studio pubblicato su Nature Astronomy. Lo riferisce Universe Today.",
   "more": [
    "Gli 'switchback' sono brusche inversioni del campo magnetico solare osservate frequentemente nel vento solare dai veicoli spaziali. Comprendere la loro origine nella corona solare aiuta gli scienziati a chiarire i meccanismi di riscaldamento e accelerazione del vento solare stesso, un aspetto fondamentale per la comprensione della meteorologia spaziale e dei suoi effetti."
   ],
