   "titolo": "L'esercito tedesco innalza il livello di allerta per il rischio di sabotaggi russi",
   "orig": "Armata germană a ridicat nivelul de alertă cu privire la sabotajele Rusiei. Document intern despre „linia roșie” depășită",
   "lead": "A Berlino, l'esercito tedesco ha innalzato per la prima volta la valutazione della minaccia di sabotaggio da parte della Russia contro le proprie truppe e strutture militari, classificandola come \"significativa\", il secondo livello su una scala interna di quattro. La decisione emerge da una valutazione del Bundeswehr diffusa dai media tedeschi WDR e Süddeutsche Zeitung, che evidenzia il superamento di una linea rossa in termini di sicurezza. Lo riferisce HotNews.",
   "more": [
    "Le forze armate dei Paesi europei monitorano costantemente la sicurezza delle proprie infrastrutture strategiche e delle basi militari di fronte a potenziali attività di spionaggio e sabotaggio. L'innalzamento dei livelli di allerta riflette la crescente tensione geopolitica e la necessità di rafforzare le misure di protezione interna e di intelligence."
   ],
