   "id": "z7b8df72f",
   "sez": "mondo",
   "titolo": "Un media pro-israeliano dietro la falsa immagine virale degli ottantageni aggrediti a Parigi",
   "orig": "Un média pro-israélien à l'origine de la fausse image virale des octogénaires agressés à Paris",
   "lead": "A Parigi, in seguito alle manifestazioni del 17 ottobre, ha iniziato a circolare una fotografia virale che pretendeva di mostrare una coppia di anziani in biancheria intima depredati dai manifestanti. L'immagine, rivelatasi falsa, è stata generata dall'intelligenza artificiale ed è stata diffusa originariamente da un sito web filo-israeliano, alimentando la disinformazione online sugli eventi nella capitale francese. Lo riferisce France 24.",
   "more": [
    "La diffusione di immagini generate artificialmente durante o subito dopo proteste e manifestazioni di piazza è una tecnica sempre più comune per influenzare l'opinione pubblica e polarizzare il dibattito politico. La verifica delle fonti visive e l'analisi forense dei contenuti digitali rappresentano strumenti essenziali per contrastare la disinformazione sui social media."
   ],
